import sys

def main():
    data = sys.stdin.read().split()
    n, B, C = int(data[0]), int(data[1]), int(data[2])
    c0, c1 = [], []
    for i in range(n):
        c = int(data[3 + 2 * i])
        if int(data[4 + 2 * i]) == 0:
            c0.append(c)
        else:
            c1.append(c)

    def greedy(costs, budget):
        costs.sort()
        cnt = 0
        for c in costs:
            if c > budget:
                break
            budget -= c
            cnt += 1
        return cnt

    best = greedy(c0[:], B)
    if B >= C:
        best = max(best, greedy(c0 + c1, B - C))
    print(best)

